import PluginManager from '@jbrowse/core/PluginManager';
import TextSearchManager from '@jbrowse/core/TextSearch/TextSearchManager';
import assemblyManagerFactory, { assemblyConfigSchemaFactory, } from '@jbrowse/core/assemblyManager';
import RpcManager from '@jbrowse/core/rpc/RpcManager';
import { cast, getSnapshot, types } from 'mobx-state-tree';
import corePlugins from '../corePlugins';
import createConfigModel from './createConfigModel';
import createSessionModel from './createSessionModel';
import { version } from '../version';
export default function createModel(runtimePlugins, makeWorkerInstance = () => {
    throw new Error('no makeWorkerInstance supplied');
}, hydrateFn, createRootFn) {
    const pluginManager = new PluginManager([...corePlugins, ...runtimePlugins].map(P => new P())).createPluggableElements();
    const Session = createSessionModel(pluginManager);
    const assemblyConfig = assemblyConfigSchemaFactory(pluginManager);
    const AssemblyManager = assemblyManagerFactory(assemblyConfig, pluginManager);
    const rootModel = types
        .model('ReactLinearGenomeView', {
        config: createConfigModel(pluginManager, assemblyConfig),
        session: Session,
        assemblyManager: types.optional(AssemblyManager, {}),
        disableAddTracks: types.optional(types.boolean, false),
        internetAccounts: types.array(pluginManager.pluggableMstType('internet account', 'stateModel')),
    })
        .volatile(self => ({
        error: undefined,
        rpcManager: new RpcManager(pluginManager, self.config.configuration.rpc, {
            WebWorkerRpcDriver: {
                makeWorkerInstance,
            },
            MainThreadRpcDriver: {},
        }),
        hydrateFn,
        createRootFn,
        textSearchManager: new TextSearchManager(pluginManager),
        adminMode: false,
        version,
    }))
        .actions(self => ({
        setSession(sessionSnapshot) {
            self.session = cast(sessionSnapshot);
        },
        renameCurrentSession(sessionName) {
            this.setSession({
                ...JSON.parse(JSON.stringify(getSnapshot(self.session))),
                name: sessionName,
            });
        },
        setError(error) {
            self.error = error;
        },
        addInternetAccount(acct) {
            self.internetAccounts.push(acct);
        },
        findAppropriateInternetAccount(location) {
            const selectedId = location.internetAccountId;
            if (selectedId) {
                const selectedAccount = self.internetAccounts.find(a => a.internetAccountId === selectedId);
                if (selectedAccount) {
                    return selectedAccount;
                }
            }
            for (const account of self.internetAccounts) {
                const handleResult = account.handlesLocation(location);
                if (handleResult) {
                    return account;
                }
            }
            return null;
        },
    }))
        .views(self => ({
        get jbrowse() {
            return self.config;
        },
    }));
    return {
        model: rootModel,
        pluginManager,
    };
}
