import { ConfigurationSchema } from '@jbrowse/core/configuration';
import { baseLinearDisplayConfigSchema } from '@jbrowse/plugin-linear-genome-view';
export default function configModelFactory(pluginManager) {
    return ConfigurationSchema('LinearAlignmentsDisplay', {
        pileupDisplay: pluginManager.getDisplayType('LinearPileupDisplay')
            .configSchema,
        snpCoverageDisplay: pluginManager.getDisplayType('LinearSNPCoverageDisplay').configSchema,
        height: {
            type: 'number',
            defaultValue: 250,
        },
    }, {
        baseConfiguration: baseLinearDisplayConfigSchema,
        explicitlyTyped: true,
    });
}
